SELECT COUNT(*) FROM ${table}
WHERE 1=1

    AND active = #{active}




    AND agent_code IN

        #{ac}





    AND (speaker_locale IS NULL OR #{speakerLocale} LIKE CONCAT(speaker_locale, '%'))


    AND (listener_locale IS NULL OR #{listenerLocale} LIKE CONCAT(listener_locale, '%'))




    AND (culture_pair IS NULL OR culture_pair = #{culturePair})



    AND version_tag = #{versionTag}

SELECT rule_id, active, agent_code, label, severity, weight, priority, pattern_type, pattern_text, case_sensitive, negate, speaker_locale, listener_locale, culture_pair, explanation_tpl, suggestion_tpl, cooldown_sec, version_tag, created_at, updated_at FROM ${table} WHERE 1=1
AND active = #{active}
AND agent_code IN
#{ac}
AND (speaker_locale IS NULL OR #{speakerLocale} LIKE CONCAT(speaker_locale, '%'))
AND (listener_locale IS NULL OR #{listenerLocale} LIKE CONCAT(listener_locale, '%'))
AND (culture_pair IS NULL OR culture_pair = #{culturePair})
AND version_tag = #{versionTag}
ORDER BY priority ASC, severity DESC, rule_id ASC LIMIT #{size} OFFSET #{offset}

SELECT rule_id, session_id, speaker_id, last_alert_at
FROM tl_manner_events
WHERE rule_id = #{ruleId}
  AND session_id <=> #{sessionId}   
  AND speaker_id <=> #{speakerId}
